const iso=(y,m,d)=>`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
function pacificDate(now=new Date()){
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
 const part=type=>parts.find(p=>p.type===type).value;
 return `${part('year')}-${part('month')}-${part('day')}`;
}
function weekStart(day=pacificDate()){const d=new Date(day+'T12:00:00');return plusDays(day,-((d.getDay()+6)%7));}
function selectToday(){selectedDate=pacificDate();year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;}
const route=()=>location.hash.slice(1)||'today';
const go=r=>{if(route()===r)render();else location.hash=r;};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
function navLink(href,label,ic){let current=route().split('/')[0];if(current==='connections')current='plugins';if(current==='studio')current='library';return `<a title="${label}" href="#${href}" class="${current===href||(href==='today'&&['calendar','timeline','readiness'].includes(current))?'active':''}" ${current===href?'aria-current="page"':''}>${icon(ic)}<span class="nav-label">${label}</span></a>`}
function beedyMark(){
 return '<svg class="beedy-mark" aria-hidden="true" viewBox="0 0 20 20" fill="none"><path d="M3 13.5 8 4.8h3.1L6 13.5H3Zm5.2 1.7 6-10.4h2.9l-6 10.4H8.2Z" fill="currentColor"/></svg>';
}
function syncNeedsAttention(message){return /conflict|retry|unavailable|offline|not connected|local changes|sync needed|backup is full|team updates available/i.test(message);}
function renderBase(){const r=route();document.title=`${r.startsWith('discussions')?'Team discussion':r.split('/')[0]==='settings'?'Settings':r==='connections'||r==='plugins'?'Plugins':r.startsWith('studio')?'Grant studio':r==='library'?'Your documents':r.startsWith('opportunities')?'Opportunities':r.startsWith('reports')?'Awards & reports':r==='calendar'?'Calendar':r==='readiness'?'Readiness':r.startsWith('applications')?'Applications':r.startsWith('tasks')?'Team tasks':r==='timeline'?'Timeline':workspacePageName(r)} · Centring`;$('#app').innerHTML=`<aside id="workspace-navigation" class="sidebar ${mobileOpen?'open':''}" aria-label="Main navigation">${workspaceNavigation()}<div class="sidebar-foot"><nav class="nav">${navLink('settings','Settings','settings')}<a href="#help">${icon('help')}Help & next steps</a></nav><a class="person person-link" aria-label="Your profile" href="#settings">${personAvatar()}<span><strong>${esc(state.name)}</strong><small>${esc(state.profileRole||'Programme lead')}</small></span></a></div></aside><header class="topbar"><button class="iconbtn mobile-toggle" data-action="menu" aria-label="${mobileOpen?'Close':'Open'} navigation" aria-expanded="${mobileOpen}">${icon(mobileOpen?'close':'menu')}</button><div class="workspace-path">${workspaceIdentity()}${r==='today'?'':`<span class="workspace-crumb" aria-hidden="true">/</span><span class="workspace-crumb">${esc(workspacePageName(r))}</span>`}</div><div class="topright"><button type="button" class="sync-attention" data-action="cloud-settings" title="${esc(cloudMessage)}" ${syncNeedsAttention(cloudMessage)?'':'hidden'}>Check sync</button><button type="button" class="beedy-launch" aria-label="Ask Beedy" aria-controls="beedy-panel" data-action="chat-toggle" aria-expanded="${chatOpen}">${beedyMark()}<span>Ask Beedy</span></button>${notificationBell()}<details class="account-menu"><summary aria-label="Open account menu">${personAvatar()}<span aria-hidden="true">⌄</span></summary><nav aria-label="Account menu"><span>${esc(state.name)}</span><a href="#settings">Your profile</a><a href="#discussions">Team discussion</a><a href="#settings/connectors">Connectors</a><button type="button" class="account-storage" data-action="cloud-settings">Workspace storage<small data-storage-status>${esc(cloudMessage)}</small></button><button type="button" class="textlink" data-demo-signout ${agentConnection==='ready'&&agentSignInMethod==='demo'?'':'hidden'}>Sign out</button></nav></details></div></header><div class="shell"><main id="main" tabindex="-1"><div data-guidance-slot>${r==='today'?'':guidancePanel(r)}</div>${page(r)}</main><footer class="footer">${r==='library'||r.startsWith('studio/')?'Documents · Shared workspace':r==='opportunities'?'Centring · Funding research':'Centring · Your grant workspace'}</footer></div>`;}
function heading(title,sub=''){return `<div class="page-heading"><h1>${title}</h1>${sub}</div>`}
function todayTabs(active){return `<nav class="tabs" aria-label="Workspace views">${[['today','Overview'],['calendar','Calendar'],['timeline','Timeline'],['readiness','Readiness']].map(([id,label])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`}
function page(r){if(r==='projects'||r.startsWith('projects/'))return projectsPage(r.split('/')[1]);if(r.startsWith('studio/'))return documentWorkspace(r.split('/')[1]);if(r==='plugins')return pluginsPage();if(r==='discussions'||r.startsWith('discussions/'))return discussionsPage(r.split('/')[1]);if(r==='tasks')return tasksPage();if(r.startsWith('tasks/'))return taskPage(r.split('/')[1]);if(r==='timeline')return timelinePage();if(r==='today')return overview();if(r==='calendar')return calendar();if(r==='readiness')return readinessPage();if(r==='opportunities')return oppPage();if(r==='applications')return applications();if(r==='applications/earlier')return applications();if(r.startsWith('applications/'))return application(r.split('/')[1]);if(r==='reports')return reports();if(r==='reports/community-arts')return report();if(r==='library')return documentLibrary();if(r==='settings'||r.startsWith('settings/'))return personalSettings(r.split('/')[1]);if(r==='connections')return personalSettings('connectors');if(r==='help')return help();return heading('Page not found')+'<a href="#today" class="btn">Back to today</a>'}
document.addEventListener('click',event=>{
 if(event.target.closest('[data-resume-draft]'))studioTab='application';
 if(event.target.closest('[data-open-support]')){studioTab='source';sourceMode='original';}
});
function oppPage(){return federal.page();}
function opportunity(id){if(id?.startsWith('federal-')){void federal.open(id.slice(8));return;}const o=opportunities.find(x=>x.id===id);if(!o)return;showDialog(`<h2 id="dialog-title">${o.name}</h2>`,`<p class="muted">${o.funder} · ${o.area}</p><p>${o.description}</p><div class="facts"><div><small>Funding range</small><strong>${o.amount}</strong></div><div><small>Application deadline</small><strong>${dateLabel(o.deadline,{day:'numeric',month:'long',year:'numeric'})}</strong></div></div><h3>Why it may fit</h3><p>${o.reason}</p><h3>Before you apply</h3><p>${o.check}</p><p class="small muted">${o.term}</p><p class="inline-message">${state.saved.includes(id)?'Saved to your shortlist. The deadline is on your calendar.':'Save this opportunity to add its deadline to your calendar.'}</p><div class="dialog-actions"><button class="btn primary" data-action="start-application" data-id="${id}">Open application</button><button class="btn" data-action="save-opportunity" data-id="${id}">${state.saved.includes(id)?'Remove from saved':'Save opportunity'}</button></div><p class="note">Example opportunity. Submit applications through the funder’s portal.</p>`)}
function calendar(){const first=new Date(year,month,1);const offset=(first.getDay()+6)%7;const start=new Date(year,month,1-offset);const all=events().filter(e=>filter==='all'||e.type===filter);return heading('Your next steps')+todayTabs('calendar')+`<div class="month-heading"><div><h2>${first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><p class="calendar-zone">Today is ${dateLabel(pacificDate(),{day:'numeric',month:'long'})} · Pacific time</p></div><div class="controls"><button class="btn" data-action="prev-month" aria-label="Previous month">‹</button><button class="btn" data-action="this-month">Today</button><button class="btn" data-action="next-month" aria-label="Next month">›</button><button class="btn primary" data-action="add-task">Add a task</button></div></div><div class="toolbar"><label for="event-filter" class="small muted">Show</label><select id="event-filter"><option value="all" ${filter==='all'?'selected':''}>All events</option><option value="task" ${filter==='task'?'selected':''}>Team tasks</option><option value="report" ${filter==='report'?'selected':''}>Report deadlines</option><option value="opportunity" ${filter==='opportunity'?'selected':''}>Grant deadlines</option><option value="funding" ${filter==='funding'?'selected':''}>Funding dates</option><option value="decision" ${filter==='decision'?'selected':''}>Decisions & follow-ups</option></select><span class="small muted">Hover or select a day to see its events.</span></div><div class="calendar"><div class="calendar-labels">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div>${d}</div>`).join('')}</div><div class="calendar-grid">${Array.from({length:Math.ceil((offset+new Date(year,month+1,0).getDate())/7)*7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=iso(d.getFullYear(),d.getMonth(),d.getDate());const ev=all.filter(e=>e.date===key);return `<button class="calday ${d.getMonth()!==month?'outside':''} ${key===selectedDate?'selected':''}" data-action="select-date" data-date="${key}" ${key===pacificDate()?'aria-current="date"':''} aria-pressed="${key===selectedDate}" aria-label="${dateLabel(key,{day:'numeric',month:'long'})}, ${ev.length} events"><span class="daynum ${key===pacificDate()?'todaynum':''}">${d.getDate()}</span>${ev.slice(0,2).map(e=>`<span class="cal-event ${e.done?'done':''}">${esc(e.title)}</span>`).join('')}${ev.length>2?`<span class="small">+${ev.length-2} more</span>`:''}</button>`}).join('')}</div></div><section class="agenda"><div class="sectionhead"><h2>${dateLabel(selectedDate,{weekday:'long',day:'numeric',month:'long'})}</h2><button class="textlink" data-action="add-task">Add task for this day</button></div>${all.filter(e=>e.date===selectedDate).map(eventRow).join('')||'<p class="muted small">No events scheduled.</p>'}</section>`}
function readinessPage(){const complete=readiness.filter(r=>state.readiness[r.id]).length;const next=readiness.find(r=>!state.readiness[r.id]);return heading('Your next steps')+todayTabs('readiness')+`<div class="readiness-top"><h2>${next?'Prepare your application':'Preparation checklist complete'}</h2><p class="intro">${next?`Next up: ${next.title.toLowerCase()}. Check each item when your team has it ready.`:'You have the basics ready. Each funder may still ask for something specific.'}</p><span class="small muted">${complete} of ${readiness.length} essentials ready</span><div class="progress" role="progressbar" aria-valuenow="${complete}" aria-valuemin="0" aria-valuemax="6" aria-label="Readiness essentials"><span style="width:${complete/6*100}%"></span></div></div>${readiness.map(r=>`<div class="checkrow"><input type="checkbox" id="ready-${r.id}" data-ready="${r.id}" ${state.readiness[r.id]?'checked':''}><label for="ready-${r.id}"><strong>${r.title}</strong><p>${r.id==='reviewer'?esc(state.name)+' will review the application before submission.':r.description}</p></label><span class="status">${state.readiness[r.id]?'Ready':'To prepare'}</span></div>`).join('')}<p class="note">This is your team’s checklist, not an eligibility decision. Ticking an item doesn’t upload or verify a document.</p><div class="report-actions"><a href="#opportunities" class="btn ${complete===6?'primary':''}">Explore opportunities</a><a href="#library" class="textlink">View preparation templates</a></div>`}
function reportsBase(){return heading('Awards & reports')+`<p class="intro">Track awards, spending, and reporting deadlines.</p><div class="simple-row" style="margin-top:25px"><div class="row-main"><h3>Welcoming Spaces</h3><p class="small muted">Neighbourhood Futures · ${money(state.report.awarded)} awarded</p></div><span class="status">${closeoutStatus()}</span><a class="btn primary" href="#reports/community-arts">${state.report.sentOn?'View record':'Review closeout'}</a></div>`}
function report(){const r=state.report;return `<a class="textlink back" href="#reports">← Awards & reports</a>`+heading('Welcoming Spaces')+`<p class="intro">Closeout record · Neighbourhood Futures</p><div class="report-sheet"><div class="reportmeta"><div><span>Due</span>${dateLabel(closeoutDue(),{day:'numeric',month:'long',year:'numeric'})}</div><div><span>Award</span>${money(r.awarded)}</div><div><span>Reviewer</span>${esc(state.name)}</div><div><span>Status</span>${closeoutStatus()}</div></div><form id="report-form"><label class="field">What did you deliver?<textarea name="summary" required ${r.sentOn?'readonly':''}>${esc(r.summary)}</textarea></label><label class="field">What difference did it make?<textarea name="impact" required ${r.sentOn?'readonly':''}>${esc(r.impact)}</textarea></label><div class="money-inputs"><label class="field">Total spent ($)<input type="number" name="spent" min="0" max="${r.awarded}" step="0.01" required ${r.sentOn?'readonly':''} value="${r.spent}"></label><div><span class="small muted">Remaining award balance</span><p id="balance" style="font-size:23px;margin-top:12px">${money(r.awarded-r.spent)}</p></div></div><p class="small muted">Confirm with your funder how any unspent funds should be handled.</p><div class="approval" ${r.sentOn?'hidden':''}><label><input type="checkbox" name="checked" ${r.checked?'checked':''}>I have checked the programme summary and spending figures.</label></div><div class="report-actions"><button class="btn primary" type="submit" name="action" value="approve" ${r.sentOn?'hidden':''}>${r.approved?'Confirm review':'Mark reviewed'}</button><button class="btn" type="submit" name="action" value="save" ${r.sentOn?'hidden':''}>Save changes</button><button class="textlink" type="submit" name="action" value="download">Export record</button></div></form><section class="section"><h3>Submission record</h3>${r.sentOn?`<p>Sent to the funder on ${dateLabel(r.sentOn,{day:'numeric',month:'long',year:'numeric'})}.</p>`:`<p class="small muted">After sending the report through the funder’s portal, record the date here.</p><form id="report-sent-form"><label class="field">Date sent<input type="date" name="sentOn" required max="${pacificDate()}" value="${pacificDate()}" ${r.approved?'':'disabled'}></label><button class="btn" ${r.approved?'':'disabled'}>Record as sent</button>${r.approved?'':'<p class="note">Review the figures first.</p>'}</form>`}</section></div>`}
function money(n){return Number(n).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2})}
function library(){return heading('Library')+'<p class="intro">Simple starting points for your team. Download a template and make it your own.</p>'+[['brief','Programme brief','Outline your idea, people, activities, and intended impact.'],['budget','Budget worksheet','List your costs, contributions, and funding request.'],['closeout','Closeout checklist','Gather the outcomes and figures for your final report.']].map(([id,title,desc])=>`<div class="simple-row"><div class="row-main"><h3>${title}</h3><p class="small muted">${desc}</p></div><button class="btn" data-action="template" data-id="${id}">Download</button></div>`).join('')+'<p class="note">Templates are text or CSV files. No organisation documents have been uploaded.</p>'}
function legacySettings(){return heading('Settings')+`<div class="settings"><form id="settings-form"><label class="field">Organisation name<input name="org" value="${esc(state.org)}" required maxlength="80"></label><label class="field">Reviewer name<input name="name" value="${esc(state.name)}" required maxlength="60"></label><button class="btn primary">Save details</button></form><section><h3>Workspace settings</h3><p class="muted small">Workspace changes sync to the cloud. Example records are included. Submit applications through the funder’s portal.</p><button class="btn danger" data-action="reset">Reset workspace</button></section></div>`}
function help(){return heading('Help & next steps')+`<p class="intro">Find grants, manage applications, and review documents. Your work syncs to your signed-in workspace.</p><div class="simple-row"><div class="row-main"><h3>Find something that fits</h3><p class="small muted">Open a grant, check the fit, and save it. Its deadline will appear in Calendar.</p></div><a class="btn" href="#opportunities">Opportunities</a></div><div class="simple-row"><div class="row-main"><h3>Get your essentials ready</h3><p class="small muted">Work through a practical six-item checklist before starting a proposal.</p></div><a class="btn" href="#readiness">Readiness</a></div><div class="simple-row"><div class="row-main"><h3>Review a report</h3><p class="small muted">Record what the award delivered, how much was spent, and when your team sent the report.</p></div><a class="btn" href="#reports/community-arts">Review report</a></div>`}
let priorFocus;
// A reminder remains outstanding until its work is completed or it is explicitly addressed.
function notificationKey(event){return JSON.stringify([event.type,event.id,event.date,event.title]);}
function notificationItems(today=new Date()){
 const until=plusDays(pacificDate(today),7);
 const addressed=state.addressedNotifications||{};
 return events().filter(e=>!e.done&&e.status!=='done'&&e.date<=until).map(e=>({...e,key:notificationKey(e),addressed:!!addressed[notificationKey(e)]}));
}
function setNotificationAddressed(key,value,today=new Date()){
 if(!notificationItems(today).some(e=>e.key===key))return false;
 const addressed={...state.addressedNotifications};
 if(value)addressed[key]=true;else delete addressed[key];
 return savePersonalState({...state,addressedNotifications:addressed});
}
function notificationBell(){
 const count=notificationItems().filter(e=>!e.addressed).length;
 return `<button class="iconbtn notification-bell" data-action="notifications" aria-label="Notifications, ${count} outstanding" title="${count} outstanding notifications">${icon('bell')}<span class="notification-count ${count?'':'is-empty'}" aria-hidden="true">${count>99?'99+':count}</span></button>`;
}
function refreshNotificationBell(){const bell=document.querySelector('.notification-bell');if(bell){const restoreFocus=priorFocus===bell;bell.outerHTML=notificationBell();if(restoreFocus)priorFocus=document.querySelector('.notification-bell');}}
function showNotifications(tab='pending'){
 const items=notificationItems(),pending=items.filter(e=>!e.addressed),addressed=items.filter(e=>e.addressed),shown=tab==='addressed'?addressed:pending;
 showDialog('<h2 id="dialog-title">Notifications</h2>',`<div class="notification-centre"><p class="muted small">Overdue items and dates in the next seven days.</p><div class="pilltabs notification-tabs"><button data-action="notification-tab" data-id="pending" aria-pressed="${tab==='pending'}" class="${tab==='pending'?'active':''}">Outstanding <span>${pending.length}</span></button><button data-action="notification-tab" data-id="addressed" aria-pressed="${tab==='addressed'}" class="${tab==='addressed'?'active':''}">Addressed <span>${addressed.length}</span></button></div><div class="notification-list">${shown.length?shown.map(e=>`<article class="notification-item"><div class="notification-symbol">${icon(e.type==='task'?'today':e.type==='report'?'file':'bell')}</div><div class="notification-content"><h3>${esc(e.title)}</h3><p>${dateLabel(e.date,{day:'numeric',month:'long',year:'numeric'})}</p><div class="notification-actions"><button class="textlink" data-action="reminder-day" data-date="${esc(e.date)}" aria-label="View ${esc(e.title)}">View in calendar</button><button class="btn" data-action="${e.addressed?'notification-restore':'notification-address'}" data-key="${esc(e.key)}" aria-label="${e.addressed?'Restore':'Mark addressed:'} ${esc(e.title)}">${e.addressed?'Restore':'Mark addressed'}</button></div></div></article>`).join(''):`<div class="notification-empty">${icon('bell')}<h3>${tab==='addressed'?'No addressed notifications':'You’re all caught up'}</h3><p>${tab==='addressed'?'Items you mark addressed will appear here.':'New reminders will appear as dates approach.'}</p></div>`}</div><p class="notification-footnote">Addressing a reminder clears it from the bell. It doesn’t complete the task or change its deadline.</p></div>`);
 document.querySelector(`.notification-tabs [data-id="${tab}"]`)?.focus();
}
function showDialog(title,body){const d=$('#detail');if(!d.open)priorFocus=document.activeElement;d.innerHTML=`<div class="dialoghead">${title}<button class="iconbtn close" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!d.open)d.showModal();}
function closeDialog(){$('#detail').close();priorFocus?.isConnected&&priorFocus.focus()}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Download ready')}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'menu':mobileOpen=!mobileOpen;render();break;case'close-dialog':closeDialog();break;case'opportunity':opportunity(id);break;case'save-opportunity':state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();opportunity(id);break;case'start-application':if(!state.applications[id]){state.applications[id]=newApplication(id);if(!state.saved.includes(id))state.saved.push(id);persist()}closeDialog();go('applications/'+id);break;case'day':selectedDate=b.dataset.date;year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;go('calendar');break;case'select-date':selectedDate=b.dataset.date;render();document.querySelector('.agenda')?.scrollIntoView({block:'nearest',behavior:'auto'});break;case'prev-month':month--;if(month<0){month=11;year--}selectedDate=iso(year,month,1);render();break;case'next-month':month++;if(month>11){month=0;year++}selectedDate=iso(year,month,1);render();break;case'this-month':selectToday();render();break;case'add-task':addTask();break;case'toggle-task':{const t=state.tasks.find(t=>t.id===id);if(t){t.done=!t.done;t.status=t.done?'done':'todo';t.checks=(t.checks||[]).map(c=>({...c,done:t.done}));persist();render()}break;}case'delete-task':showDialog('<h2 id="dialog-title">Remove this task?</h2>',`<p>This removes it from your calendar.</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">Keep task</button><button class="btn danger" data-action="confirm-delete-task" data-id="${id}">Remove task</button></div>`);break;case'confirm-delete-task':state.tasks=state.tasks.filter(t=>t.id!==id);persist();closeDialog();render();toast('Task removed');break;case'open-report':closeDialog();go('reports/community-arts');break;case'notifications':showNotifications();break;case'notification-tab':showNotifications(b.dataset.id);break;case'notification-address':if(setNotificationAddressed(b.dataset.key,true)){refreshNotificationBell();showNotifications();}break;case'notification-restore':if(setNotificationAddressed(b.dataset.key,false)){refreshNotificationBell();showNotifications('addressed');}break;case'reminder-day':closeDialog();selectedDate=b.dataset.date;year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;go('calendar');break;case'template':if(id==='budget')download('Centring-budget-template.csv','Item,Quantity,Unit cost,Total cost,Notes\nTeaching artists,,,,\nMaterials,,,,\nVenue,,,,\nAccessibility support,,,,\nOther contributions,,,,','text/csv');else download('Centring-'+id+'-template.txt',id==='brief'?'PROGRAMME BRIEF\n\nProgramme name:\n\nPeople and place:\n\nWhat will you do?\n\nWhat difference will it make?\n\nActivities and timeline:\n\nFunding requested:\n\nTeam reviewer:\n':'CLOSEOUT CHECKLIST\n\n[ ] Confirm delivered activities\n[ ] Gather participant feedback\n[ ] Reconcile spending against budget\n[ ] Check remaining funds with the funder\n[ ] Review supporting evidence\n[ ] Get final team approval\n[ ] Submit through the funder portal\n[ ] Keep a copy of the confirmation\n');break;case'reset':showDialog('<h2 id="dialog-title">Start fresh?</h2>','<p>This clears your saved opportunities, application drafts, tasks, discussions, and checklist changes. Uploaded documents and their drafts are kept in your document library.</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">Keep my changes</button><button class="btn danger" data-action="confirm-reset">Reset workspace</button></div>');break;case'confirm-reset':state=defaults();migrateDemo();persist();closeDialog();go('today');toast('Workspace reset');break;}});
document.addEventListener('input',e=>{if(e.target.name==='spent'&&$('#balance'))$('#balance').textContent=money(state.report.awarded-Number(e.target.value));if(e.target.closest('#report-form')&&e.target.name!=='checked')$('#report-form [name=checked]').checked=false;});
document.addEventListener('change',e=>{if(e.target.dataset.ready){state.readiness[e.target.dataset.ready]=e.target.checked;persist();const id=e.target.id;render();document.getElementById(id)?.focus();}if(e.target.id==='event-filter'){filter=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='task-form'){const title=String(d.get('title')).trim();if(!title){f.elements.title.setCustomValidity('Give your task a name.');f.elements.title.reportValidity();f.elements.title.oninput=()=>f.elements.title.setCustomValidity('');return}state.tasks.push({id:crypto.randomUUID(),title,date:String(d.get('date')),type:'task',done:false});selectedDate=String(d.get('date'));year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;persist();closeDialog();render();toast('Task added to your calendar')}if(f.id==='application-form-legacy'){const id=f.dataset.id;state.applications[id]={title:String(d.get('title')).trim(),description:String(d.get('description')).trim(),amount:Number(d.get('amount')),status:e.submitter?.value==='review'?'review':'draft'};persist();render();toast(e.submitter?.value==='review'?'Draft ready for your team to review':'Draft saved')}if(f.id==='report-sent-form'){
 const sentOn=String(d.get('sentOn')||'');
 if(!state.report.approved||state.report.sentOn||!/^\d{4}-\d{2}-\d{2}$/.test(sentOn)||sentOn>pacificDate())return;
 state.report.sentOn=sentOn;persist();render();toast('Report submission recorded');return;
}if(f.id==='report-form'){const action=e.submitter?.value||'save';if(state.report.sentOn&&action!=='download')return;const checked=d.get('checked')==='on';if(action==='approve'&&!checked){toast('Check the summary and spending figures before approving.');f.elements.checked.focus();return}const changed=state.report.summary!==d.get('summary')||state.report.impact!==d.get('impact')||state.report.spent!==Number(d.get('spent'));state.report={...state.report,summary:String(d.get('summary')),impact:String(d.get('impact')),spent:Number(d.get('spent')),checked,approved:action==='approve'||(!changed&&checked&&state.report.approved)};persist();if(action==='download'){const r=state.report;download('Welcoming-Spaces-closeout.txt',`WELCOMING SPACES CLOSEOUT RECORD\nSample data\n\nOrganisation: ${state.org}\nReviewer: ${state.name}\nStatus: ${closeoutStatus()}\nDue: ${dateLabel(closeoutDue())}\n\nWHAT WE DELIVERED\n${r.summary}\n\nTHE DIFFERENCE IT MADE\n${r.impact}\n\nAward: ${money(r.awarded)}\nSpent: ${money(r.spent)}\nRemaining: ${money(r.awarded-r.spent)}\n\nReport sent: ${r.sentOn||'Not recorded'}\n`)}else toast(action==='approve'?'Closeout figures reviewed.':'Report saved');render()}if(f.id==='settings-form'){state.org=String(d.get('org')).trim()||defaults().org;state.name=String(d.get('name')).trim()||defaults().name;persist();render();toast('Details saved')}});
window.addEventListener('hashchange',()=>{mobileOpen=false;if($('#detail').open)closeDialog();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog()}});

