function mountDocumentVoice(){const d=studioDoc();if(!d)return;const target=document.querySelector('.studio-tabs')||document.querySelector('[aria-label="Document views"]');target?.append(voiceButton(()=>{const edits=d.review?.edits||[];if(!edits.length)return null;return {kind:'edits',total:edits.length,edits:edits.slice(0,12).map(e=>({status:e.status||'suggested',before:String(e.before||'').slice(0,500),after:String(e.after||e.suggested||'').slice(0,500),reason:String(e.reason||'').slice(0,300)}))};}));}

function render(){const activePrompt=document.activeElement?.id==='home-prompt'?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;document.body.classList.toggle('nav-pinned',navigationPinned);document.body.classList.toggle('today-view',route()==='today');hideDayPreview();syncBeedyDocument();stopSourceViewer();renderBase();if(activePrompt){const input=document.querySelector('#home-prompt');if(input){input.focus({preventScroll:true});input.setSelectionRange(...activePrompt);}}document.querySelectorAll('[data-organisation-banner]').forEach(blendOrganisationBanner);federal.mount();if(route().startsWith('studio/'))mountDocumentVoice();document.body.classList.toggle('chat-open',chatOpen&&route()!=='today');document.body.classList.toggle('home-conversation',chatOpen&&route()==='today');document.body.classList.toggle('chat-expanded',chatOpen&&chatExpanded);placeChatPanel();if(route().startsWith('studio/')&&shouldMountSourceViewer(studioDoc(),studioTab,sourceMode))mountSourceViewer(studioDoc(),studioTab==='review'?{review:true,mode:reviewMode,onSelect:selectReviewSuggestion}:{});}
function daysBetween(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function plusDays(d,n){const date=new Date(d+'T12:00:00');date.setDate(date.getDate()+n);return iso(date.getFullYear(),date.getMonth(),date.getDate())}
function taskProgress(t){return t.done?100:t.checks?.length?Math.round(t.checks.filter(c=>c.done).length/t.checks.length*100):0}
function applicationProgress(a){if(['submitted','awarded','received','declined'].includes(a.status))return {value:a.status==='received'||a.status==='declined'?100:a.status==='awarded'?67:a.acknowledged?33:0,label:'Follow-up milestones',detail:a.status==='declined'?'Decision recorded · Application closed':`${Number(!!a.acknowledged)+Number(['awarded','received'].includes(a.status))+Number(a.status==='received')} of 3 milestones recorded`};const n=a.checks.filter(c=>c.done).length;return {value:Math.round(n/a.checks.length*100),label:'Preparation',detail:`${n} of ${a.checks.length} steps complete`};}
function progressHTML(p){return `<div class="work-progress"><div><span>${p.label}</span><strong>${p.value}%</strong></div><div class="progress" role="progressbar" aria-label="${p.label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.value}"><span style="width:${p.value}%"></span></div><small>${p.detail}</small></div>`}
function grant(id){return opportunities.find(o=>o.id===id)}
function ownerSelect(value,name='owner'){return `<select name="${name}"><option value="">Unassigned</option>${members.map(m=>`<option value="${m.id}" ${value===m.id?'selected':''}>${esc(m.name())} · ${m.role}</option>`).join('')}</select>`}
function relatedSelect(value){
 const choices=[...Object.keys(state.applications).map(id=>[id,state.applications[id].title]),...studioDocuments.filter(d=>d.applicationDraft&&!d.legacyCase).map(d=>[d.id,d.applicationDraft.title])];
 return `<select name="related"><option value="">General team task</option>${choices.map(([id,label])=>`<option value="${esc(id)}" ${value===id?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
}
function taskRow(t){
 return `<div class="work-line"><button class="work-check" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}" aria-pressed="${!!t.done}">${t.done?'✓':''}</button><a href="#tasks/${esc(t.id)}" class="work-name"><strong>${esc(t.title)}</strong>${linkedTaskContext(t)?'<small>'+esc(linkedTaskContext(t))+'</small>':''}</a><span class="work-person">${personAvatar(t.owner)}<span>${esc(ownerName(t.owner))}</span></span><time datetime="${esc(t.date)}">${dateLabel(t.date)}</time><span class="work-state">${esc(taskStates[t.status]||'To do')}</span></div>`;
}
function tasksPage(){
 const visible=state.tasks.filter(t=>(taskOwner==='all'||t.owner===taskOwner)&&(taskFilter==='all'||(taskFilter==='complete'?t.done:taskFilter==='active'?!t.done:t.status===taskFilter))).sort((a,b)=>a.date.localeCompare(b.date));
 const groups=[['doing','In progress'],['todo','To do'],['done','Completed']];
 const earlier=visible.filter(t=>t.related&&state.applications[t.related]&&!caseDocument(t.related));
 const current=visible.filter(t=>!earlier.includes(t));
 return `<div class="matter-room"><header class="matter-head"><h1>Team tasks</h1><button class="btn primary" data-action="add-task">+ New task</button></header><div class="task-controls"><div class="desk-tabs">${[['active','Open'],['complete','Completed'],['all','All tasks']].map(([key,label])=>`<button data-work-filter="${key}" aria-pressed="${taskFilter===key}">${label}</button>`).join('')}</div><label>Assignee <select id="task-owner"><option value="all">Everyone</option>${members.map(m=>`<option value="${m.id}" ${taskOwner===m.id?'selected':''}>${esc(m.name())}</option>`).join('')}<option value="" ${taskOwner===''?'selected':''}>Unassigned</option></select></label></div>
 ${groups.map(([key,label])=>{const rows=current.filter(t=>(t.done?'done':t.status||'todo')===key);return rows.length?`<section class="work-group"><header><i class="work-dot ${key}"></i><h2>${label}</h2><small>${rows.length}</small></header>${rows.map(taskRow).join('')}</section>`:'';}).join('')}${earlier.length?`<details class="earlier-records" ${current.length?'':'open'}><summary>Earlier project tasks · ${earlier.length}</summary>${earlier.map(taskRow).join('')}</details>`:''}${visible.length?'':'<p class="desk-empty">No tasks in this view.</p>'}</div>`;
}
function taskPage(id){
 const t=state.tasks.find(t=>t.id===id);if(!t)return heading('Task unavailable');
 const label=linkedTaskContext(t),parent=taskCase(t);
 return `<div class="matter-room"><a href="#tasks" class="matter-back">← Team tasks</a><header class="matter-head"><div><p class="matter-kicker">${esc(taskStates[t.status]||'To do')}</p><h1>${esc(t.title)}</h1></div><button class="btn" data-work-edit="${esc(id)}">Edit task</button></header><div class="matter-layout"><section class="matter-main"><div class="desk-section-head"><h2>Checklist</h2><button class="textlink" data-work-edit="${esc(id)}">+ Add step</button></div>${(t.checks||[]).map((c,i)=>`<button class="check-line" data-work-step="${i}" data-id="${esc(id)}" aria-pressed="${!!c.done}"><i>${c.done?'✓':''}</i><span>${esc(c.name)}</span></button>`).join('')||'<p class="desk-empty">No checklist steps.</p>'}<div class="desk-section-head"><h2>Notes</h2></div><p class="work-notes">${esc(t.notes||'No notes yet.')}</p></section><aside class="matter-aside"><section><h2>Task details</h2><dl><dt>Assignee</dt><dd>${esc(ownerName(t.owner))}</dd><dt>Starts</dt><dd>${dateLabel(t.start||t.date)}</dd><dt>Due</dt><dd>${dateLabel(t.date)}</dd></dl>${progressHTML({label:'Checklist',value:taskProgress(t),detail:(t.checks||[]).filter(c=>c.done).length+' of '+(t.checks||[]).length+' steps complete'})}</section>
 ${label||t.documentId||t.discussionId?`<section><h2>Related work</h2>${parent?'<a class="case-file" href="#applications/'+esc(parent.id)+'">'+esc(label)+' →</a>':esc(label)}${t.documentId?'<a class="case-file" href="#studio/'+esc(t.documentId)+'">Open source document →</a>':''}${t.discussionId?'<a class="case-file" href="#discussions/'+esc(t.discussionId)+'">Team discussion →</a>':''}</section>`:''}</aside></div></div>`;
}
function taskFields(t,fit){
 return `<label class="field">Task<input name="title" maxlength="120" required placeholder="What needs doing?" value="${esc(t.title||'')}"></label><div class="work-fields"><label class="field">Assignee${ownerSelect(t.owner)}</label><label class="field">Due<input type="date" name="date" required value="${esc(t.date)}"></label></div>
 ${fit?`<p class="task-context">Opportunity · ${esc(fit.title)}</p>`:''}<details class="task-options"><summary>Details and scheduling</summary><label class="field">Start date<input type="date" name="start" required value="${esc(t.start)}"></label><label class="field">Related application${relatedSelect(t.related)}</label><label class="field">Notes<textarea name="notes" maxlength="6000" rows="3">${esc(t.notes||'')}</textarea></label></details>`;
}
function addTask(context={}){
 const linked=context.caseId||((route().startsWith('applications/')||route().startsWith('studio/'))?route().split('/')[1]:'');
 caseDialog('New task',`<form id="new-team-task" class="work-form" data-return-research="${esc(context.returnNotice?.research)}" data-return-live="${esc(context.returnNotice?.live)}" data-opportunity="${esc(context.key||'')}" data-title="${esc(context.title||'')}">${taskFields({owner:'sarah',related:linked,start:pacificDate(),date:pacificDate()},context.key?context:null)}<button class="btn primary">Create task</button></form>`);
}
function editTaskDialog(id){
 const t=state.tasks.find(t=>t.id===id);if(!t)return;
 caseDialog('Edit task',`<form id="task-edit-form" data-id="${esc(id)}" class="work-form">${taskFields(t,t.opportunityKey?{title:t.opportunityTitle}:null)}<label class="field">Status<select name="status">${Object.entries(taskStates).map(([key,label])=>`<option value="${key}" ${t.status===key?'selected':''}>${label}</option>`).join('')}</select></label><div>${(t.checks||[]).map((step,i)=>`<label class="step-check"><input type="checkbox" name="step-${i}" ${step.done?'checked':''}>${esc(step.name)}</label>`).join('')}</div><label class="field">Add step<input name="newstep" maxlength="100"></label><div class="dialog-actions"><button class="btn primary" value="save">Save task</button><button class="btn" value="complete">Mark complete</button></div></form>`);
}
document.addEventListener('click',event=>{
 const filter=event.target.closest('[data-work-filter]');if(filter){taskFilter=filter.dataset.workFilter;render();}
});
const applicationStages={draft:'Drafting',ready:'Ready for review',review:'In review',reviewed:'Reviewed',submitted:'Submitted',awarded:'Awarded',declined:'Declined'};
function caseDocument(id){
 return studioDocuments.find(d=>d.applicationDraft&&(d.id===id||d.legacyCase===id));
}
function caseIdFor(doc){return doc.legacyCase||doc.id;}
function legacyNarrative(a){
 return {title:a.title,sections:[{question:'Project overview',answer:a.description||''},{question:'Funding requested',answer:money(a.amount)}]};
}
function caseInfo(id){
 const legacy=state.applications[id],doc=caseDocument(id);
 if(!legacy&&!doc)return null;
 const draft=doc?.applicationDraft,notice=legacy?grant(id):doc.opportunity||draft.grant;
 const submitted=legacy?.submissionCopy||doc?.submissionCopy||
  (id==='heritage'&&legacy?.reference==='LCF-2026-041'?{...heritageExample,date:legacy.submitted,reference:legacy.reference,example:true}:null);
 const key=opportunityKey(draft?.researchId?{researchId:draft.researchId}:notice);
 const tasks=state.tasks.filter(t=>t.related===id||(!t.related&&key&&t.opportunityKey===key));
 const checks=legacy?legacy.checks.map(c=>c.done):(draft?.sections||[]).map(s=>s.status==='approved');
 return {id,legacy,doc,notice,submitted,tasks,key,title:draft?.title||legacy?.title,stage:applicationStage(doc,legacy),
  agency:notice?.agency||notice?.funder||draft?.sources?.find(s=>s.role==='notice')?.name||'',
  copy:draft?narrativeCopy(draft):legacyNarrative(legacy),progress:submitted?.preparation||recordProgress(checks,tasks)};
}
function caseFiles(c){
 const ids=new Set([...(c.legacy?.linkedFiles||c.doc?.linkedFiles||[]),c.doc?.referenceSource?.id,c.doc?.applicationTemplate?.id]);
 return studioDocuments.filter(d=>d.id!==c.doc?.id&&(ids.has(d.id)||d.application===c.id||(d.importedGrantId&&opportunityKey({id:d.importedGrantId})===c.key)));
}
function stageLabel(stage){return applicationStages[stage]||stages[stage]||stage;}
function stageTag(stage){return `<span class="case-stage stage-${esc(stage)}"><i></i>${esc(stageLabel(stage))}</span>`;}
function applications(){
 const ids=[...studioDocuments.filter(d=>d.applicationDraft&&!d.legacyCase).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(d=>d.id),...Object.keys(state.applications)];
 const records=ids.map(caseInfo).filter(Boolean);
 const visible=records.filter(c=>appFilter==='all'||(appFilter==='active'?preparingStage(c.stage):appFilter==='waiting'?c.stage==='submitted':['awarded','received','declined'].includes(c.stage)));
 const earlier=visible.filter(c=>c.legacy&&!c.doc);
 const current=visible.filter(c=>!earlier.includes(c));
 const row=c=>`<a class="register-row" href="#applications/${esc(c.id)}"><span class="register-name"><i>${icon('file')}</i><span><strong>${esc(c.title)}</strong><small>${esc(c.agency)}</small></span></span>${stageTag(c.stage)}<span class="mini-meter"><progress max="100" value="${c.progress.value}"></progress><small>${c.progress.value}%</small></span><span class="register-end">${c.tasks.filter(t=>!t.done).length} ${icon('arrow')}</span></a>`;
 return `<div class="matter-room"><header class="matter-head"><div><h1>Applications</h1></div><a class="btn primary" href="#opportunities">Find opportunities ${icon('arrow')}</a></header>
 <div class="desk-tabs">${[['all','All applications'],['active','In preparation'],['waiting','Submitted'],['awards','Decisions']].map(([id,label])=>`<button data-case-filter="${id}" aria-pressed="${appFilter===id}">${label}</button>`).join('')}</div>
 <div class="case-register"><div class="register-labels"><span>Application / funder</span><span>Status</span><span>Preparation</span><span>Open tasks</span></div>
 ${current.map(row).join('')}${earlier.length?`<details class="earlier-records" ${current.length?'':'open'}><summary>Earlier application records · ${earlier.length}</summary>${earlier.map(row).join('')}</details>`:''}${visible.length?'':'<p class="desk-empty">No applications in this view.</p>'}</div></div>`;
}
function application(id){
 const c=caseInfo(id);
 if(!c)return heading(studioLoaded?'Application unavailable':'Opening application…')+'<a href="#applications">All applications</a>';
 const active=preparingStage(c.stage), files=caseFiles(c), archived=c.submitted;
 const button=(action,label,primary=false)=>`<button class="btn ${primary?'primary':''}" data-case-action="${action}" data-id="${esc(id)}">${label}</button>`;
 const url=c.notice?.url||c.doc?.applicationDraft.sources.find(s=>s.role==='notice')?.url;
 const sourceLink=/^https?:\/\//i.test(url||'')?`<a class="textlink" href="${esc(url)}" rel="noopener noreferrer" target="_blank">Open funder portal ↗</a>`:'';
 const copy=active?c.copy:archived||c.copy;
 const review=state.fitReviews?.[c.key];
 return `<div class="matter-room"><a class="matter-back" href="#applications">← Applications</a><header class="matter-head"><div><p class="matter-kicker">${esc(c.notice?.name||c.agency)}</p><h1>${esc(c.title)}</h1><p class="matter-byline">${esc(c.agency)} ${stageTag(c.stage)}</p></div>
 ${active?button('write','Open in Documents',true):archived?button('read','View submitted copy',true):''}</header>
 <div class="matter-layout"><section class="matter-main"><div class="desk-section-head"><h2>Application document</h2>${active?button('submit','Record submission'):''}</div>
 ${documentSheet(copy,{label:active?'Working draft':archived?(archived.example?'Illustrative submitted copy':'Submitted copy'):'Saved application details',action:archived&&!active?`<small>${dateLabel(archived.date)}</small>`:''})}
 <div class="desk-section-head"><h2>Assigned tasks <small>${c.tasks.length}</small></h2>${button('task','+ Add task')}</div>${c.tasks.map(taskRow).join('')||'<p class="desk-empty">No tasks assigned to this application.</p>'}</section>
 <aside class="matter-aside"><section><h2>${archived?.preparation?'Completion at submission':'Completion'}</h2>${progressHTML(c.progress)}<small>${c.legacy?'Preparation checklist and assigned tasks':'Approved answers and completed tasks'}</small></section>
 <section><h2>Application details</h2><dl><dt>Status</dt><dd>${esc(stageLabel(c.stage))}</dd>${c.legacy?`<dt>Owner</dt><dd>${esc(ownerName(c.legacy.owner))}</dd><dt>Requested</dt><dd>${esc(money(c.legacy.amount))}</dd>`:''}${(c.legacy?.deadline||c.notice?.deadline)?'<dt>Deadline</dt><dd>'+dateLabel(c.legacy?.deadline||c.notice.deadline)+'</dd>':''}${archived?'<dt>Submitted</dt><dd>'+dateLabel(archived.date)+'</dd>':''}${archived?.reference?'<dt>Reference</dt><dd>'+esc(archived.reference)+'</dd>':''}${c.doc?.funderDecision?.date?'<dt>Decision date</dt><dd>'+dateLabel(c.doc.funderDecision.date)+'</dd>':''}${review?'<dt>Fit decision</dt><dd>'+esc(review.decision)+'</dd>':''}</dl>${review?.note?'<p class="desk-empty">'+esc(review.note)+'</p>':''}${sourceLink}
 ${c.legacy?button('details',active?'Manage preparation':'Manage follow-up'):c.stage==='submitted'?button('decision','Record funder decision'):''}</section>
 <section><div class="desk-section-head"><h2>Related documents</h2>${button('link','+ Link')}</div>${files.map(d=>`<a class="case-file" data-open-support href="#studio/${esc(d.id)}">${icon('file')}<span>${esc(d.name)}</span></a>`).join('')||'<p class="desk-empty">No documents linked.</p>'}</section></aside></div></div>`;
}
function returnToNotice(form){
 if(form.dataset.returnResearch)research.open(form.dataset.returnResearch);
 else if(form.dataset.returnLive)federal.resumeNotice(form.dataset.returnLive);
}
function caseDialog(title,body){showDialog('<h2 id="dialog-title">'+esc(title)+'</h2>',body);}
async function openCaseDraft(c){
 if(!studioLoaded){await initStudio();c=caseInfo(c.id);}
 if(c.doc){closeDialog();openApplicationDraft(c.doc,true);return;}
 const copy=c.submitted||c.copy;
 const draft={title:copy.title,organisation:state.org,form_status:'working_outline',grant:c.notice,
  fit:{assessment:'uncertain',summary:c.notice?.check||'Review the funder requirements.',eligibility_checks:[]},
  sources:[{id:'notice',role:'notice',name:c.notice.name,text:c.notice.description}],
  sections:copy.sections.map((s,i)=>({...s,id:'answer-'+i,status:'draft',evidence:[],missing:[],verifiedQuestion:false}))};
 const doc=await saveApplicationDraft(draft,{legacyCase:c.id});closeDialog();openApplicationDraft(doc);
}
function saveCaseFields(c,fields){
 if(c.legacy){return savePersonalState({...state,applications:{...state.applications,[c.id]:{...c.legacy,...fields}}});}
 return saveStudioDocument({...c.doc,...fields});
}
function taskCase(task){
 if(task.related)return caseInfo(task.related);
 if(!task.opportunityKey)return null;
 const doc=studioDocuments.find(d=>d.applicationDraft&&opportunityKey(d.applicationDraft.researchId?{researchId:d.applicationDraft.researchId}:d.opportunity)===task.opportunityKey);
 return doc?caseInfo(caseIdFor(doc)):null;
}
function linkedTaskContext(task){
 const record=taskCase(task);
 return record?.title||task.opportunityTitle||'';
}
function fitControls(grant){
 const key=opportunityKey(grant),review=state.fitReviews?.[key];
 const tasks=state.tasks.filter(t=>t.opportunityKey===key&&!t.related);
 return `<div class="fit-actions" data-notice-research="${esc(grant.researchId||'')}" data-notice-live="${esc(grant.id||'')}"><button type="button" data-fit-review="${esc(key)}" data-title="${esc(grant.name)}">${review?esc(review.decision)+' · Edit fit review':'Review fit'}</button><button type="button" data-fit-task="${esc(key)}" data-title="${esc(grant.name)}">+ Assign task</button></div>${review?.note?'<p class="fit-team-note">'+esc(review.note)+'</p>':''}${tasks.map(t=>'<a class="case-file" href="#tasks/'+esc(t.id)+'">'+icon('check')+esc(t.title)+' · '+esc(ownerName(t.owner))+'</a>').join('')}`;
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-case-action],[data-case-filter],[data-fit-task],[data-fit-review],[data-work-edit],[data-work-step]');
 if(!button)return;
 try{
 if(button.dataset.caseFilter){appFilter=button.dataset.caseFilter;render();return;}
 const origin=button.closest('dialog .fit-actions')?.dataset;
 const returnNotice=origin?{research:origin.noticeResearch,live:origin.noticeLive}:null;
 if(button.dataset.fitTask){addTask({key:button.dataset.fitTask,title:button.dataset.title,returnNotice});return;}
 if(button.dataset.fitReview){
  const key=button.dataset.fitReview,review=state.fitReviews?.[key]||{};
  caseDialog('Review opportunity fit',`<form id="fit-review-form" data-return-research="${esc(returnNotice?.research)}" data-return-live="${esc(returnNotice?.live)}" data-key="${esc(key)}" class="work-form"><h3>${esc(button.dataset.title)}</h3><label class="field">Team assessment<select name="decision">${['Needs checking','Pursue','Pass'].map(value=>`<option ${review.decision===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="field">Reason and eligibility checks<textarea name="note" maxlength="3000" rows="3" placeholder="Consider programme alignment, geography and applicant requirements.">${esc(review.note||'')}</textarea></label><button class="btn primary">Save fit review</button></form>`);return;
 }
 if(button.dataset.workEdit){editTaskDialog(button.dataset.workEdit);return;}
 if(button.dataset.workStep!==undefined){
  const task=state.tasks.find(t=>t.id===button.dataset.id),check=task?.checks[Number(button.dataset.workStep)];
  if(check){check.done=!check.done;task.done=task.checks.every(s=>s.done);task.status=task.done?'done':task.checks.some(s=>s.done)?'doing':'todo';persist();render();}
  return;
 }
 const c=caseInfo(button.dataset.id);if(!c)return;
 switch(button.dataset.caseAction){
 case 'write':button.disabled=true;await openCaseDraft(c);break;
 case 'task':addTask({caseId:c.id});break;
 case 'details':caseDialog(c.title,preparingStage(c.stage)?applicationEditor(c.id,c.legacy):submissionTracking(c.id,c.legacy));break;
 case 'read':if(c.submitted)caseDialog('Submitted application',documentSheet(c.submitted,{label:c.submitted.example?'Illustrative submitted copy':'Submitted copy',full:true})+`<div class="dialog-actions"><button class="btn" data-case-action="download" data-id="${esc(c.id)}">Download submitted copy</button><button class="btn" data-case-action="write" data-id="${esc(c.id)}">Open working draft</button></div>`);break;
 case 'download':{
  if(!c.submitted)break;
  const file=await newDraftDocx([c.submitted.title,...c.submitted.sections.map(s=>s.question+'\n'+s.answer)].join('\n\n'));
  const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=c.submitted.title+' — submitted.docx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;
 }
 case 'link':{
  const available=studioDocuments.filter(d=>d.id!==c.doc?.id&&!caseFiles(c).some(link=>link.id===d.id));
  caseDialog('Link a document',available.length?`<form class="work-form" id="case-link-form" data-id="${esc(c.id)}"><label class="field">File from Documents<select name="file">${available.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select></label><button class="btn primary">Link document</button></form>`:'<p>All available files are linked.</p><a class="btn" href="#library">Open Documents</a>');break;
 }
 case 'submit':{
  if(!preparingStage(c.stage))break;
  if(c.legacy){recordSubmission(c.id);break;}
  caseDialog('Record submission',`<form id="case-submission-form" data-id="${esc(c.id)}" class="work-form"><p>Save a copy of the application sent to the funder.</p><label class="field">Submission date<input type="date" name="date" required value="${pacificDate()}" max="${pacificDate()}"></label><label class="field">Funder reference (optional)<input name="ref" maxlength="160"></label><button class="btn primary">Confirm submission</button></form>`);break;
 }
 case 'decision':{
  if(c.stage!=='submitted')break;
  caseDialog('Record funder decision',`<form id="case-decision-form" data-id="${esc(c.id)}" class="work-form"><label class="field">Decision date<input type="date" name="date" required value="${pacificDate()}" min="${esc(c.submitted?.date||'')}" max="${pacificDate()}"></label><div class="dialog-actions"><button name="outcome" value="awarded" class="btn">Confirm award</button><button name="outcome" value="declined" class="btn">Confirm decline</button></div></form>`);break;
 }
 }
 }catch(error){toast(error.message);button.disabled=false;}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['fit-review-form','case-link-form','case-submission-form','case-decision-form'].includes(f.id))return;
 e.preventDefault();const values=new FormData(f),buttons=f.querySelectorAll('button');
 if(f.dataset.saving)return;f.dataset.saving='true';buttons.forEach(b=>b.disabled=true);
 try{
 let ok;
 if(f.id==='fit-review-form'){
  ok=savePersonalState({...state,fitReviews:{...state.fitReviews,[f.dataset.key]:{decision:String(values.get('decision')),note:String(values.get('note')).trim()}}});
 }else{
  const c=caseInfo(f.dataset.id);if(!c)throw Error('Application unavailable.');
  if(f.id==='case-link-form'){
   const id=String(values.get('file'));if(!studioDoc(id))throw Error('File unavailable.');
   ok=await saveCaseFields(c,{linkedFiles:[...new Set([...(c.legacy?.linkedFiles||c.doc?.linkedFiles||[]),id])]});
  }else if(f.id==='case-submission-form'){
   if(!preparingStage(c.stage))throw Error('This application already has a submission or decision.');
   const date=String(values.get('date')||'');
   if(!date||date>pacificDate())throw Error('Choose the date you submitted.');
   ok=await saveCaseFields(c,{submissionCopy:{...narrativeCopy(c.doc.applicationDraft),preparation:c.progress,date,reference:String(values.get('ref')||'').trim()}});
  }else{
   const outcome=e.submitter?.value,date=String(values.get('date')||'');
   if(c.stage!=='submitted'||!['awarded','declined'].includes(outcome))throw Error('Choose the confirmed funder decision.');
   if(!date||date>pacificDate()||(c.submitted?.date&&date<c.submitted.date))throw Error('Check the decision date.');
   ok=await saveCaseFields(c,{funderDecision:{outcome,date}});
  }
 }
 if(ok){closeDialog();render();returnToNotice(f);toast('Saved');}
 }catch(error){toast(error.message);}finally{delete f.dataset.saving;buttons.forEach(b=>b.disabled=false);}
});
function applicationEditor(id,a){return `<form id="working-application" data-id="${esc(id)}" class="work-form"><div class="money-inputs"><label class="field">Funding requested ($)<input name="amount" type="number" min="1" max="1000000" value="${a.amount}" required></label><label class="field">Application owner${ownerSelect(a.owner)}</label></div><h3>Preparation checklist</h3>${a.checks.map((c,i)=>`<label class="step-check"><input name="prep-${i}" type="checkbox" ${c.done?'checked':''}><span>${c.name}</span></label>`).join('')}<div class="report-actions"><button class="btn primary" name="action" value="save">Save progress</button><button class="btn" name="action" value="review">Ask for review</button></div></form>`;}

function submissionTracking(id,a){const p=applicationProgress(a);return `<div class="report-sheet"><div class="milestones">${[['Receipt confirmed',a.acknowledged],['Decision recorded',['awarded','received','declined'].includes(a.status)],['Funding received',a.status==='received']].map(([l,done])=>`<div><span class="circle ${done?'complete':''}">${done?'✓':''}</span><span>${l}${a.status==='declined'&&l==='Funding received'?' · Not applicable':''}</span></div>`).join('')}</div><div class="reportmeta"><div><span>Submitted</span>${dateLabel(a.submitted)}</div><div><span>Reference</span>${esc(a.reference||'Not recorded')}</div><div><span>${a.status==='submitted'?'Expected decision':'Decision recorded'}</span>${a.decisionDate?dateLabel(a.decisionDate):'Not recorded'}</div>${a.status==='awarded'||a.status==='received'?`<div><span>${a.status==='received'?'Received':'Expected funding'}</span>${dateLabel(a.status==='received'?a.receivedDate:a.fundingDate)}</div>`:''}</div><form id="tracking-form" data-id="${id}"><label class="field">Owner${ownerSelect(a.owner)}</label><div class="money-inputs"><label class="field">${a.status==='submitted'?'Expected decision date':'Decision date'}<input name="decisionDate" type="date" value="${a.decisionDate||''}" required min="${a.submitted}" ${a.status!=='submitted'?'readonly':''}></label><label class="field">Next follow-up date<input name="followup" type="date" value="${a.followup||''}" min="${a.submitted}"></label></div>${a.status==='awarded'?`<label class="field">Expected funding date<input type="date" name="fundingDate" value="${a.fundingDate}" min="${a.submitted}" required></label>`:''}<label class="step-check"><input type="checkbox" name="acknowledged" ${a.acknowledged?'checked':''} ${a.status!=='submitted'?'disabled':''}><span>We have confirmation that the funder received our application.</span></label><label class="field extra-step">Follow-up notes<textarea name="trackingNotes">${esc(a.trackingNotes||'')}</textarea></label><button class="btn" type="submit">Save tracking details</button></form><div class="report-actions">${a.status==='submitted'?`<button class="btn primary" data-action="record-decision" data-id="${id}">Record a decision</button>`:a.status==='awarded'?`<button class="btn primary" data-action="record-funding" data-id="${id}">Record funding received</button>`:''}</div><p class="note">Expected dates are planning estimates. Updating this tracker doesn’t contact the funder or move money.</p><h3 style="margin-top:30px">Activity</h3><div class="activity">${[...(a.history||[])].reverse().map(h=>`<p><span>${dateLabel(h.date)}</span>${esc(h.label)}</p>`).join('')}</div></div>`}
function events(){const list=[...federal.events(),{id:'report',title:'Final report due',date:closeoutDue(),type:'report',done:!!state.report.sentOn},...state.tasks];for(const o of opportunities){const a=state.applications[o.id];if(a){list.push({id:o.id,title:o.name,date:a.deadline,type:'opportunity',done:!['draft','review'].includes(a.status),application:true});if(['submitted','awarded'].includes(a.status)){if(a.followup)list.push({id:o.id,title:'Follow up: '+o.name,date:a.followup,type:'decision',application:true});if(a.status==='submitted'&&a.decisionDate)list.push({id:o.id,title:'Expected decision: '+o.name,date:a.decisionDate,type:'decision',application:true})}if(['awarded','received'].includes(a.status))list.push({id:o.id,title:(a.status==='received'?'Received: ':'Funding expected: ')+o.name,date:a.status==='received'?a.receivedDate:a.fundingDate,type:'funding',done:a.status==='received',application:true})}else if(state.saved.includes(o.id))list.push({id:o.id,title:o.name,date:o.deadline,type:'opportunity',done:false});}return list.filter(e=>e.date).sort((a,b)=>a.date.localeCompare(b.date))}
function eventRow(e){return `<div class="simple-row"><span class="circle ${e.done?'complete':''}">${e.done?'✓':''}</span><div class="row-main"><h3>${esc(e.title)}</h3><p class="small muted">${e.type==='task'?esc(ownerName(e.owner))+' · '+taskStates[e.status]:e.type==='funding'?(e.done?'Funds recorded as received':'Expected date · Not yet received'):e.type==='decision'?'Planning date':e.type==='report'?'Report deadline':e.label?esc(e.label):e.forecast?'Forecast date · Not confirmed':'Application deadline'}</p></div>${e.type==='task'?`<a class="btn" href="#tasks/${e.id}">Open task</a>`:e.application?`<a class="btn" href="#applications/${e.id}">Open application</a>`:`<button class="btn" data-action="${e.type==='report'?'open-report':'opportunity'}" data-id="${e.id}">Open ${e.type==='report'?'report':'opportunity'}</button>`}</div>`}
function reports(){const awards=Object.entries(state.applications).filter(([id,a])=>['awarded','received'].includes(a.status));return reportsBase()+`<section class="section"><h2>Funding on its way</h2>${awards.map(([id,a])=>`<div class="simple-row"><div class="row-main"><h3>${grant(id).name}</h3><p class="small muted">${money(a.amount)} · ${a.status==='received'?'Received '+dateLabel(a.receivedDate):'Expected '+dateLabel(a.fundingDate)} · ${esc(ownerName(a.owner))}</p></div><a class="btn" href="#applications/${id}">Open award</a></div>`).join('')||'<p class="muted">No awards recorded yet.</p>'}</section>`}
function timelinePage(){const end=plusDays(timelineStart,41);const rows=[...Object.entries(state.applications).map(([id,a])=>({id,title:grant(id).name,owner:a.owner,start:a.start,end:['draft','review'].includes(a.status)?a.deadline:a.status==='submitted'?a.decisionDate:a.status==='received'?a.receivedDate:a.fundingDate||a.decisionDate,type:'application',progress:applicationProgress(a).value,funding:a.status==='awarded'?a.fundingDate:null})),...state.tasks.map(t=>({id:t.id,title:t.title,owner:t.owner,start:t.start,end:t.date,type:'task',progress:taskProgress(t)}))].filter(r=>r.end>=timelineStart&&r.start<=end);return heading('Your next steps')+todayTabs('timeline')+`<div class="month-heading"><div><h2>The work ahead</h2><p class="small muted">${dateLabel(timelineStart)} – ${dateLabel(end,{day:'numeric',month:'short',year:'numeric'})}</p></div><div class="controls"><button class="btn" data-action="timeline-prev" aria-label="Previous six weeks">‹</button><button class="btn" data-action="timeline-now">This period</button><button class="btn" data-action="timeline-next" aria-label="Next six weeks">›</button></div></div><p class="small muted">Open a bar to see its tasks or application. ◆ marks an expected funding date.</p><div class="gantt-scroll"><div class="gantt"><div class="gantt-head"><span>Work & owner</span><div class="gantt-weeks">${Array.from({length:6},(_,i)=>`<span>${dateLabel(plusDays(timelineStart,i*7))}</span>`).join('')}</div></div>${rows.map(r=>{const left=Math.max(0,daysBetween(timelineStart,r.start))/42*100;const right=Math.min(42,daysBetween(timelineStart,r.end)+1)/42*100;const funding=r.funding&&r.funding>=timelineStart&&r.funding<=end?Math.min(98,daysBetween(timelineStart,r.funding)/42*100):null;return `<div class="gantt-row"><a class="gantt-label" href="#${r.type==='task'?'tasks':'applications'}/${r.id}"><strong>${esc(r.title)}</strong><span>${esc(ownerName(r.owner))} · ${dateLabel(r.end)}</span></a><div class="gantt-track"><a href="#${r.type==='task'?'tasks':'applications'}/${r.id}" class="gantt-bar ${r.type}" style="left:${left}%;width:${Math.max(1.5,right-left)}%" aria-label="${esc(r.title)}, ${dateLabel(r.start)} to ${dateLabel(r.end)}, ${r.progress}%"><span style="width:${r.progress}%"></span><b>${r.progress}%</b></a>${funding!==null?`<a class="funding-diamond" href="#applications/${r.id}" style="left:${funding}%" aria-label="Expected funding for ${esc(r.title)} on ${dateLabel(r.funding)}">◆</a>`:''}</div></div>`}).join('')||'<div class="empty">No work scheduled in this period.</div>'}</div></div><p class="note">Application bars show preparation or follow-up windows. You can edit task dates and expected decision or funding dates in their details.</p>`}
function chatContext(){const r=route();if(r.startsWith('discussions')){const t=discussionById(r.split('/')[1])||discussionResults()[0];if(t)return {kind:'discussion',id:t.id,title:t.title,related:t.related};}if(r.startsWith('studio/')){const d=studioDoc();if(d)return {kind:'document',id:d.id,title:d.name,related:d.application||'',owner:'sarah',date:''};}if(r.startsWith('tasks/')){const t=state.tasks.find(t=>t.id===r.split('/')[1]);if(t)return {kind:'task',id:t.id,title:t.title,related:t.related,owner:t.owner,date:t.date};}if(r.startsWith('applications/')){const id=r.split('/')[1],a=state.applications[id];if(a)return {kind:'application',id,title:a.title,related:id,owner:a.owner,date:a.followup||a.fundingDate||a.deadline};const doc=caseDocument(id);if(doc)return {kind:'application',id,title:doc.applicationDraft.title,related:id,date:doc.opportunity?.deadline||''};}if(r.startsWith('reports'))return {kind:'report',id:'report',title:'Welcoming Spaces',date:closeoutDue(),owner:'sarah',related:''};return {kind:'workspace',id:r,title:({today:'Workspace home',calendar:'Your calendar',timeline:'Your timeline',readiness:'Grant readiness',tasks:'Team tasks',applications:'Your applications',opportunities:'Grant opportunities',library:'Your documents',plugins:'Your plugins',connections:'Your connections',settings:'Your profile',help:'Help & next steps'})[r]||'Your workspace',date:pacificDate(),owner:'sarah',related:''};}
function placeChatPanel(){const home=document.querySelector('#home-conversation-slot');(home&&chatOpen?home:$('#app')).insertAdjacentHTML('beforeend',chatPanel());}
function refreshChat(){const wasDocked=document.body.classList.contains('chat-open');const readingPosition=wasDocked?($('.shell')?.scrollTop||0):window.scrollY;const opening=chatOpen&&!$('#beedy-panel')?.classList.contains('is-open');syncBeedyDocument();document.body.classList.toggle('chat-open',chatOpen&&route()!=='today');document.body.classList.toggle('home-conversation',chatOpen&&route()==='today');document.body.classList.toggle('chat-expanded',chatOpen&&chatExpanded);$('#beedy-panel')?.remove();placeChatPanel();document.querySelectorAll('.beedy-launch').forEach(b=>b.setAttribute('aria-expanded',String(chatOpen)));if(route()!=='today'&&wasDocked!==chatOpen){if(chatOpen){$('.shell').scrollTop=readingPosition;}else{window.scrollTo({top:readingPosition,behavior:'instant'});}}if(opening)$('#beedy-panel')?.classList.add('is-entering');if(chatOpen){const log=$('.chat-messages');const latest=log.querySelector('.chat-message:last-of-type');log.scrollTop=agentBusy||agentError||visibleRun()?log.scrollHeight:latest?.classList.contains('assistant')?Math.max(0,latest.offsetTop-12):state.chat.length?log.scrollHeight:0;}}
function recordSubmission(id){showDialog('<h2 id="dialog-title">Record your submission</h2>',`<p class="small muted">Use this after submitting through the funder’s portal. This updates your application record.</p><form id="submission-form" data-id="${id}"><label class="field">Submission date<input type="date" name="submitted" value="${pacificDate()}" max="${pacificDate()}" required></label><label class="field">Confirmation reference<input name="reference" placeholder="Optional reference from the funder" maxlength="100"></label><label class="field">Expected decision date<input name="decisionDate" type="date" value="${plusDays(pacificDate(),30)}" min="${pacificDate()}" required></label><label class="step-check"><input name="acknowledged" type="checkbox"><span>We have a submission receipt.</span></label><button class="btn primary">Save submission record</button></form>`)}
function recordDecision(id){showDialog('<h2 id="dialog-title">Record the funder’s decision</h2>',`<form id="decision-form" data-id="${id}"><fieldset><legend>Funder decision</legend><label class="step-check"><input type="radio" name="outcome" value="awarded" required> Award confirmed</label><label class="step-check"><input type="radio" name="outcome" value="declined" required> Not awarded</label></fieldset><label class="field">Decision date<input name="date" type="date" value="${pacificDate()}" min="${state.applications[id].submitted}" max="${pacificDate()}" required></label><div id="award-fields"><label class="field">Award amount ($)<input name="amount" type="number" min="1" max="1000000" value="${state.applications[id].amount}" required></label><label class="field">Expected funding date<input name="fundingDate" type="date" min="${pacificDate()}" required></label></div><button class="btn primary">Save decision</button><p class="note">Record a confirmed decision, not a prediction.</p></form>`)}
function recordFunding(id){showDialog('<h2 id="dialog-title">Have the funds arrived?</h2>',`<p>${money(state.applications[id].amount)} · ${grant(id).name}</p><form id="funding-form" data-id="${id}"><label class="field">Date received<input type="date" name="receivedDate" value="${pacificDate()}" min="${state.applications[id].decisionDate}" max="${pacificDate()}" required></label><label class="step-check"><input type="checkbox" required><span>I have confirmed receipt of the full award.</span></label><button class="btn primary">Record receipt</button><p class="note">This records a status only. It does not move money.</p></form>`)}
function createAwardTasks(id,a){
 if(state.tasks.some(t=>t.related===id&&t.awardSetup))return;
 state.tasks.push({id:crypto.randomUUID(),title:'Set up the award budget',owner:'alex',start:pacificDate(),date:a.fundingDate,status:'todo',done:false,type:'task',related:id,awardSetup:true,notes:'Check the award agreement and confirm the expected payment date.',checks:[{name:'Review award conditions',done:false},{name:'Create the budget code',done:false}]},{id:crypto.randomUUID(),title:'Plan the funded programme kickoff',owner:'jordan',start:a.fundingDate,date:plusDays(a.fundingDate,7),status:'todo',done:false,type:'task',related:id,awardSetup:true,notes:'Coordinate delivery after the expected funding date. Confirm funds have arrived before committing costs.',checks:[{name:'Confirm delivery dates',done:false},{name:'Brief the programme team',done:false}]});
}
// Additional interactions are explicit user actions; Beedy never silently changes records.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'chat-clear':clearBeedyChat();break;case'chat-undo-clear':undoClearBeedyChat();break;case'chat-expand':{const log=$('.chat-messages'),position=log?.scrollTop;chatExpanded=!chatExpanded;refreshChat();if(position!==undefined)$('.chat-messages').scrollTop=position;$('.chat-expand')?.focus({preventScroll:true});break;}case'chat-upload':$('#beedy-upload')?.click();break;case'chat-toggle':chatOpen=!chatOpen;refreshChat();if(chatOpen){checkAgentConnection();$('#beedy-message').focus()}break;case'chat-close':chatOpen=false;refreshChat();$('.beedy-launch')?.focus();break;case'chat-prompt':replyToBeedy(b.dataset.prompt);break;case'chat-create-task':{const m=state.chat.find(m=>m.id===id);if(!m?.suggestion)return;const t=m.suggestion;showDialog('<h2 id="dialog-title">Review Beedy’s suggested task</h2>',`<form id="new-team-task"><label class="field">Task name<input name="title" value="${esc(t.title)}" maxlength="120" required></label><label class="field">Assigned to${ownerSelect(t.owner)}</label><div class="money-inputs"><label class="field">Start date<input type="date" name="start" value="${pacificDate()}" required></label><label class="field">Due date<input name="date" type="date" value="${t.date}" min="${pacificDate()}" required></label></div><label class="field">Related application${relatedSelect(t.related)}</label><label class="field">Notes<textarea name="notes">${esc(t.notes)}</textarea></label><button class="btn primary">Create task</button></form>`);break;}case'application-filter':appFilter=id;render();break;case'record-submission':recordSubmission(id);break;case'record-decision':recordDecision(id);break;case'record-funding':recordFunding(id);break;case'timeline-prev':timelineStart=plusDays(timelineStart,-42);render();break;case'timeline-next':timelineStart=plusDays(timelineStart,42);render();break;case'timeline-now':timelineStart=weekStart();render();break;}});
document.addEventListener('change',e=>{if(e.target.id==='task-owner'){taskOwner=e.target.value;render()}if(e.target.id==='task-filter'){taskFilter=e.target.value;render()}if(e.target.matches('#decision-form [name=outcome]')){const hide=e.target.value==='declined';$('#award-fields').hidden=hide;$('#award-fields').querySelectorAll('input').forEach(i=>{i.disabled=hide;i.required=!hide})}});
document.addEventListener('input',e=>{if(e.target.id==='beedy-message'){chatDraft=e.target.value;e.target.style.height='auto';e.target.style.height=Math.min(140,e.target.scrollHeight)+'px';}if(e.target.name==='start'&&e.target.form?.elements.date)e.target.form.elements.date.min=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&chatOpen&&!$('#detail').open){chatOpen=false;refreshChat();$('.beedy-launch')?.focus()}if(e.target.id==='beedy-message'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(chatDraft.trim())replyToBeedy(chatDraft.trim())}});
document.addEventListener('submit',e=>{const f=e.target,d=new FormData(f),id=f.dataset.id;let message='';
 if(f.id==='beedy-chat-form'){e.preventDefault();const q=String(d.get('message')).trim();if(q)replyToBeedy(q);return}
 if(f.id==='new-team-task'){const title=String(d.get('title')).trim();if(!title){toast('Give your task a name.');return}if(d.get('date')<d.get('start')){toast('The due date must be on or after the start date.');return}const task={id:crypto.randomUUID(),title,owner:String(d.get('owner')),start:String(d.get('start')),date:String(d.get('date')),related:String(d.get('related')||''),opportunityKey:f.dataset.opportunity||'',opportunityTitle:f.dataset.title||'',notes:String(d.get('notes')||''),status:'todo',done:false,type:'task',checks:[{name:'Complete the task',done:false}]};state.tasks.push(task);persist();closeDialog();if(route()==='tasks')go('tasks/'+task.id);else render();returnToNotice(f);toast('Task created');return}
 if(f.id==='task-edit-form'){const t=state.tasks.find(t=>t.id===id);if(d.get('date')<d.get('start')){toast('The due date must be on or after the start date.');return}let status=String(d.get('status'));let checks=t.checks.map((c,i)=>({...c,done:d.get('step-'+i)==='on'}));const extra=String(d.get('newstep')).trim();if(extra)checks.push({name:extra,done:false});if(e.submitter?.value==='complete'){status='done';checks=checks.map(c=>({...c,done:true}))}else if(status==='done'&&checks.some(c=>!c.done))status='doing';else if(checks.length&&checks.every(c=>c.done))status='done';else if(checks.some(c=>c.done))status='doing';Object.assign(t,{title:String(d.get('title')).trim()||t.title,owner:String(d.get('owner')),start:String(d.get('start')),date:String(d.get('date')),related:String(d.get('related')),notes:String(d.get('notes')),status,done:status==='done',checks});if(t.related){delete t.opportunityKey;delete t.opportunityTitle;}closeDialog();message='Task updated';}
 if(f.id==='working-application'){const a=state.applications[id];const checks=a.checks.map((c,i)=>({...c,done:d.get('prep-'+i)==='on'}));Object.assign(a,{amount:Number(d.get('amount')),owner:String(d.get('owner')),checks,status:checks.every(c=>c.done)&&e.submitter?.value==='review'?'review':'draft'});message=e.submitter?.value==='review'&&a.status!=='review'?'Progress saved. Complete all five steps before team review.':'Application progress saved';}
 if(f.id==='submission-form'){const a=state.applications[id],c=caseInfo(id);if(!a.submissionCopy)a.submissionCopy={...c.copy,preparation:c.progress,date:String(d.get('submitted')),reference:String(d.get('reference')||'')};Object.assign(a,{status:'submitted',submitted:String(d.get('submitted')),reference:String(d.get('reference')),decisionDate:String(d.get('decisionDate')),acknowledged:d.get('acknowledged')==='on',followup:plusDays(String(d.get('submitted')),14)});a.history.push({label:'Submission recorded',date:a.submitted});message='Submission recorded. Nothing was sent.';closeDialog();}
 if(f.id==='tracking-form'){const a=state.applications[id];Object.assign(a,{owner:String(d.get('owner')),decisionDate:String(d.get('decisionDate')),followup:String(d.get('followup')),trackingNotes:String(d.get('trackingNotes')),acknowledged:a.status==='submitted'?d.get('acknowledged')==='on':a.acknowledged});if(d.get('fundingDate'))a.fundingDate=String(d.get('fundingDate'));message='Tracking details saved';}
 if(f.id==='decision-form'){const a=state.applications[id];a.status=String(d.get('outcome'));a.decisionDate=String(d.get('date'));a.acknowledged=true;if(a.status==='awarded'){a.amount=Number(d.get('amount'));a.fundingDate=String(d.get('fundingDate'));createAwardTasks(id,a);}a.history.push({label:a.status==='awarded'?'Award confirmed':'Not awarded; decision recorded',date:a.decisionDate});message='Decision recorded';closeDialog();}
 if(f.id==='funding-form'){const a=state.applications[id];a.status='received';a.receivedDate=String(d.get('receivedDate'));a.history.push({label:'Full award received',date:a.receivedDate});message='Funding receipt recorded';closeDialog();}
 if(message){persist();if(f.id==='working-application'||f.id==='tracking-form')closeDialog();render();toast(message)}
});

// Live agent and dashboard insights are loaded after the core workspace definitions.
let agentConnection='checking',agentSignInMethod='demo',agentBusy=false,agentError='',insightSelected=null;
// Start a fresh conversation when moving away from the guided demo engine.
if(state.agentVersion!==3){state.chat=[];state.agentVersion=3;state.appliedChanges=[];persist();}
function isClearChatRequest(text){return /^(?:(?:can|could|would) you\s+)?(?:please\s+)?(?:clear|reset|delete)\s+(?:(?:all|this|the|my|current|our)\s+)*(?:chat(?:\s+(?:session|history|conversation))?|conversation)(?:\s+(?:please|now))?[.!?]*$/i.test(text.trim());}
function clearBeedyChat(){
 if(agentBusy||applicationGenerating){toast('Wait for Beedy to finish, then clear the chat.');return false;}
 if(!state.chat.length&&!chatDraft&&!agentError){toast('This chat is already empty.');return false;}
 const next={...state,chat:[],chatUndo:{messages:state.chat,draft:isClearChatRequest(chatDraft)?'':chatDraft,at:Date.now()}};
 if(!savePersonalState(next))return false;
 chatDraft='';agentError='';if(currentRun?.state!=='active')currentRun=null;refreshChat();$('#beedy-message')?.focus();toast('Chat cleared. Your documents and work are unchanged.');return true;
}
function undoClearBeedyChat(){
 if(agentBusy||state.chat.length||!Array.isArray(state.chatUndo?.messages))return false;
 const backup=state.chatUndo,next={...state,chat:backup.messages};delete next.chatUndo;
 if(!savePersonalState(next))return false;
 chatDraft=backup.draft||'';agentError='';refreshChat();toast('Chat restored.');return true;
}
function syncBeedyDocument(){const d=selectContextDocument(route(),studioDocuments,pinnedDocumentId,excludedDocumentId);beedyDocument=documentContext(d);if(d)pinnedDocumentId=d.id;}
function currentPageContext(){return {...chatContext(),route:route(),attachedDocument:beedyDocument?{id:beedyDocument.id,name:beedyDocument.name}:null,documentTab:route().startsWith('studio/')?studioTab:null,selectedDate:route()==='calendar'?selectedDate:null,calendarMonth:route()==='calendar'?`${year}-${month+1}`:null,timelineStart:route()==='timeline'?timelineStart:null,taskFilters:route()==='tasks'?{status:taskFilter,owner:taskOwner}:null,applicationFilter:route()==='applications'?appFilter:null,discussionId:route().startsWith('discussions')?(discussionById(route().split('/')[1])||discussionResults()[0])?.id:null};}
function agentSnapshot(){syncBeedyDocument();const page=currentPageContext();return {documents:beedyDocument?[beedyDocument]:[],documentLibrary:studioDocuments.slice(0,100).map(d=>({id:d.id,name:d.name,words:wordCount(d.text),attached:d.id===beedyDocument?.id})),currentPage:page,organisationProfile,profile:{name:state.name,organisation:state.org,mission:state.mission||'',role:state.profileRole||'Programme lead'},plugins:{mode:'Workflow previews only; no mailbox access',preferences:state.connectionPlans||{}},discussions:discussionContextSnapshot(state.discussions||[],page.discussionId),demoDate:pacificDate(),currentDate:pacificDate(),timeZone:'America/Los_Angeles',organisation:state.org,tasks:state.tasks,applications:{...state.applications,...Object.fromEntries(studioDocuments.filter(d=>d.applicationDraft).slice(0,50).map(d=>[d.id,{title:d.applicationDraft.title,status:applicationStage(d,state.applications[caseIdFor(d)]),updatedAt:d.updatedAt,documentId:d.id}]))},opportunities:federal.context(),calendar:events(),readiness:state.readiness,report:state.report,team:members.map(m=>({id:m.id,name:m.name(),role:m.id==='sarah'?(state.profileRole||m.role):m.role}))};}
