let currentRun=null;
const activityHeaders={'Content-Type':'application/json',Accept:'application/x-ndjson'};
function visibleRun(){
 const view=route();
 if(currentRun&&(currentRun.state==='active'||currentRun.view===view||view==='studio/'+currentRun.output?.id))return currentRun;
 return null;
}
function completedDraftRun(run){
 return {title:run.title,state:'done',steps:run.steps.map(step=>({...step,state:step.state==='active'?'done':step.state}))};
}
function activityPanel(run,compact=false){
 if(!run)return '';
 const labels={active:'In progress',done:'Complete',failed:'Stopped',unavailable:'Unavailable'};
 const steps=run.steps.map(step=>`<li class="run-step is-${esc(step.state)}"><span class="run-marker" aria-label="${labels[step.state]}">${step.state==='done'?'✓':step.state==='active'?'':'!'}</span><div><strong>${esc(step.label)}</strong>${step.detail?`<small>${esc(step.detail)}</small>`:''}</div></li>`).join('');
 return `<details class="run-card" ${compact?'':'open'}><summary><span>Beedy activity</span><small>${labels[run.state]}</small></summary><div class="run-content"><h3>${esc(run.title)}</h3><ol>${steps}</ol>${run.error?`<p role="alert">${esc(run.error)}</p>`:''}${run.output?`<a class="run-output" href="#studio/${esc(run.output.id)}">${icon('file')}<span>${esc(run.output.name)}</span>${icon('arrow')}</a>`:''}${run.cancel&&run.state==='active'?'<button type="button" class="textlink" data-cancel-draft>Cancel draft</button>':''}</div></details>`;
}
function updateActivity(){
 const host=document.querySelector('[data-run-live]');
 if(!host)return;
 const log=host.closest('.chat-messages');
 const follow=log&&log.scrollHeight-log.clientHeight-log.scrollTop<35;
 const previous=host.querySelector('details'),open=previous?.open;
 host.innerHTML=activityPanel(visibleRun());
 if(open===false&&host.firstElementChild)host.firstElementChild.open=false;
 if(follow)log.scrollTop=log.scrollHeight;
}
function startRun(title,{split=false,cancel=null}={}){
 const run={title,view:route(),steps:[],state:'active',cancel};currentRun=run;
 if(split){chatOpen=true;chatExpanded=false;refreshChat();}
 updateActivity();
 return run;
}
function advanceRun(run,label,detail='',state='active'){
 const previous=run.steps.at(-1);
 if(previous?.state==='active')previous.state=state==='unavailable'?'unavailable':'done';
 if(label)run.steps.push({label,detail:String(detail||'').slice(0,280),state:'active'});
 updateActivity();
}
function finishRun(run,error='',output=null){
 run.state=error?'failed':'done';run.error=error;run.cancel=null;
 if(output)run.output={id:output.id,name:output.name};
 if(run.steps.at(-1)?.state==='active')run.steps.at(-1).state=run.state;
 updateActivity();
}
document.addEventListener('click',event=>{if(event.target.closest('[data-cancel-draft]'))currentRun?.cancel?.();});
function chatPanel(){const c=chatContext();const pastDraft=!visibleRun()&&route().startsWith('studio/')?studioDoc()?.draftActivity:null;const disabled=agentBusy||applicationGenerating||agentConnection!=='ready';return `<aside id="beedy-panel" class="beedy-panel ${visibleRun()?'has-activity':''} ${applicationGenerating?'drafting-now':''} ${state.chat.length?'has-conversation':''} ${agentConnection==='signin'?'auth-required':''} ${chatOpen?'is-open':''}" aria-label="Beedy assistant" ${chatOpen?'':'inert'}>
 <header class="beedy-head"><div class="assistant-emblem">${beedyMark()}</div><div class="beedy-title"><h2>Beedy</h2><span>${agentConnection==='ready'?'Grants, documents, and team tasks':agentConnection==='signin'?'Sign in to start chatting':agentConnection==='checking'?'Checking connection…':agentConnection==='missing'?'Awaiting AI connection':'Connection unavailable'}</span></div><button class="iconbtn chat-expand" data-action="chat-expand" aria-label="${chatExpanded?'Narrow':'Expand'} Beedy" aria-pressed="${chatExpanded}" title="${chatExpanded?'Narrow':'Expand'} chat">${icon(chatExpanded?'contract':'expand')}</button><button class="iconbtn" data-action="chat-close" aria-label="Close Beedy">${icon('close')}</button></header>
 <div class="beedy-context">${icon('layers')}<span>Your workspace</span><span aria-hidden="true">/</span><strong>${esc(profileMemory?.projects.find(p=>p.id===selectedChatProject())?.name||c.title)}</strong><button type="button" class="chat-clear" data-action="chat-clear" ${agentBusy||(!state.chat.length&&!chatDraft&&!agentError)?'disabled':''} title="${agentBusy?'Wait for Beedy to finish':'Clear this conversation; keep your documents and work'}">Clear chat</button></div>${state.chatUndo&&!state.chat.length?'<div class="chat-cleared" role="status"><span>Chat cleared</span><button type="button" data-action="chat-undo-clear">Undo</button></div>':''}
 <div class="chat-messages" role="log" aria-label="Conversation with Beedy">${!state.chat.length&&!visibleRun()&&!pastDraft?`<div class="chat-welcome"><h3>How can I help?</h3><p>Ask about a grant, review a document, or update a team task.</p></div>`:''}${pastDraft?activityPanel(pastDraft,true):''}${state.chat.map(chatMessage).join('')}<div data-run-live aria-live="polite">${activityPanel(visibleRun())}</div>${agentError&&visibleRun()?.error!==agentError?`<div class="agent-error" role="alert">${esc(agentError)}</div>`:''}</div>
 ${agentConnection==='signin'?`<div class="connection-note beedy-signin"><strong>Welcome to your workspace</strong><p>Sign in to continue. Your uploads and question stay in this browser.</p><a class="btn primary" data-action="beedy-signin" href="${esc(signInPath(route(),agentSignInMethod))}" target="_top">Sign in to Centring</a><button class="textlink" data-action="agent-recheck">Check sign-in status</button></div>`:''}${agentConnection==='unavailable'?'<div class="connection-note"><p>Couldn’t check your connection.</p><button class="textlink" data-action="agent-recheck">Try again</button></div>':''}${agentConnection==='missing'?'<div class="connection-note"><strong>Ready to connect</strong><p>Enable the secure AI connection to start a conversation.</p><button class="textlink" data-action="agent-recheck">Check connection</button></div>':''}
 <div class="chat-bottom"><div class="chat-suggestions"><button data-action="chat-prompt" data-prompt="Which deadlines need our attention this week?" ${disabled?'disabled':''}>Upcoming deadlines ${icon('arrow')}</button><button data-action="chat-prompt" data-prompt="Search live federal grants for our programme. Ask me for our focus area and nonprofit status if you need them." ${disabled?'disabled':''}>Find grants ${icon('arrow')}</button></div>
 <input type="file" id="beedy-upload" hidden accept=".pdf,.docx,.txt,.md,.png,.jpg,.jpeg" aria-label="Upload a document to Beedy"><form id="beedy-chat-form"><div class="chat-compose">${documentSelector()}<label class="sr-only" for="beedy-message">Message Beedy</label><textarea id="beedy-message" name="message" placeholder="Ask Beedy…" rows="1" maxlength="4000" required>${esc(chatDraft)}</textarea><div class="composer-controls"><button type="button" class="iconbtn" data-action="chat-upload" aria-label="Upload a document" title="Upload a document">${icon('upload')}</button><span>${beedyDocument?'Document + workspace':'Workspace context'}</span><button class="iconbtn send-message" type="submit" aria-label="Send message" ${disabled?'disabled':''}>${icon('send')}</button></div></div></form>
 <p class="chat-disclosure">${agentConnection==='ready'?'Check facts and sources before using AI suggestions.':agentConnection==='signin'?'Sign in to start chatting. Your files stay in your workspace.':'Your workspace is available while AI connects.'}</p></div></aside>`;}
function documentSelector(){return `<details class="chat-context-picker"><summary>${icon(beedyDocument?'file':'layers')}<span>${esc(beedyDocument?.name||'Add document context')}</span><small>${beedyDocument?(beedyDocument.truncated?'Partial source':'Attached'):''}</small>${icon('chevron')}</summary><div class="context-picker-body"><label class="beedy-document-select">Document for this conversation<select id="beedy-document-select" aria-label="Document for Beedy"><option value="">No document</option>${studioDocuments.map(d=>`<option value="${esc(d.id)}" ${beedyDocument?.id===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><small>Selected text is shared with AI when you send.</small></label>${beedyDocument?'<button type="button" class="textlink" data-action="document-detach">Remove document</button>':''}</div></details>`;}
function localTarget(change){return changeTarget(change,state)}
function proposalLabel(p){const c=p.change;const labels={task_create:'Create a task',task_update:'Update task',application_update:'Update application',readiness_update:'Update readiness'};return labels[c.kind]||'Suggested change';}
function patchLabel(key,value){const labels={owner:'Assigned to',start:'Start date',date:'Due date',deadline:'Application deadline',decisionDate:'Expected decision',fundingDate:'Expected funding',followup:'Follow-up date',trackingNotes:'Notes',related:'Related application',ready:'Ready',status:'Status',title:'Task',notes:'Notes'};return {label:labels[key]||key,value:key==='owner'?ownerName(value):key==='status'?taskStates[value]:key==='related'?(grant(value)?.name||'General team task'):key==='ready'?(value?'Yes':'No'):String(value)};}
function proposalCard(p,messageId){const target=localTarget(p.change),patch=p.change.patch;const title=patch.title||target?.title||(p.change.kind==='application_update'?grant(p.change.id)?.name:'')||proposalLabel(p);const details=Object.entries(patch).map(([key,value])=>{const label=patchLabel(key,value);return `<div><dt>${label.label}</dt><dd>${esc(label.value)}</dd></div>`}).join('');return `<div class="proposal-card"><div class="proposal-topline">${icon(p.applied?'check':'file')}<span>${p.applied?'Applied in your workspace':p.undone?'Change undone':proposalLabel(p)}</span><span class="proposal-state">${p.applied?'Done':p.undone?'Undone':'For review'}</span></div><h3>${esc(title)}</h3><p>${patch.owner?esc(ownerName(patch.owner))+' · ':''}${patch.date?'Due '+esc(dateLabel(patch.date,{day:'numeric',month:'short',year:'numeric'})):p.applied?'Updated in this workspace.':'Review the details before applying.'}</p><details class="proposal-details"><summary>View change details ${icon('chevron')}</summary><dl>${details}</dl></details>${p.applied?`<button class="textlink" data-action="agent-undo" data-message="${esc(messageId)}" data-id="${esc(p.id)}">Undo change</button>`:p.undone?'<span class="small muted">Ask Beedy for a fresh proposal.</span>':`<button class="btn primary" data-action="agent-apply" data-message="${esc(messageId)}" data-id="${esc(p.id)}">Apply change ${icon('arrow')}</button>`}</div>`;}
async function replyToBeedy(question,{insightDocumentId=null,insightGrantId=null,displayQuestion=question}={}){if(agentBusy||applicationGenerating||!question.trim())return;if(isClearChatRequest(question)){clearBeedyChat();return;}if(agentConnection!=='ready'){agentError=agentConnection==='signin'?'Use Sign in to Centring below. Your question hasn’t been sent.':agentConnection==='missing'?'Beedy is waiting for the secure AI connection. Your message hasn’t been sent.':'The AI connection is unavailable. Check the connection and try again.';chatDraft=question;refreshChat();return;}agentBusy=true;agentError='';const run=startRun('Respond to your request');advanceRun(run,'Prepare workspace context',beedyDocument?.name||state.org);const started=Date.now();const sourceName=beedyDocument?.name||'';const history=state.chat.slice(-12).map(m=>({role:m.role,content:m.text+(m.grantResults?.length?'\nDisplayed opportunities in order: ' + m.grantResults.map(g=>g.id+' '+g.name).join('\n'):'')}));state.chat.push({id:crypto.randomUUID(),role:'user',text:displayQuestion});chatDraft='';persist();if(route().startsWith('studio/')&&studioTab==='review')render();else refreshChat();try{if(beedyDocument){try{await ensureDocumentReview(beedyDocument.id);}catch{/* Reading still works when a file cannot support safe editing. */}}const requestWorkspace=agentSnapshot();const r=await fetch('/api/beedy/chat',{method:'POST',headers:activityHeaders,body:JSON.stringify({message:question,projectId:selectedChatProject()||undefined,history,workspace:requestWorkspace,context:chatContext().title}),signal:AbortSignal.timeout(120000)});const d=await readBeedyResponse(r,(...event)=>advanceRun(run,...event));if(!r.ok){if(d.code==='connection_required')agentConnection='missing';if(r.status===401||d.code==='sign_in_required')agentConnection='signin';throw new Error(d.error||'Beedy could not complete this request.')}if(d.source!=='openai'||typeof d.answer!=='string'||!Array.isArray(d.proposals))throw new Error('Beedy returned an unexpected response.');for(const p of d.proposals){validateChange(p.change,state);if(typeof p.id!=='string'||typeof p.before!=='string')throw new Error('Beedy returned an invalid change.');}let editDocumentId=null;const incoming=d.documentEdits||[];if(incoming.length){const docId=incoming[0].documentId;const source=requestWorkspace.documents.find(x=>x.id===docId);validateDocumentEdits({document_id:docId,edits:incoming.map(e=>({block_id:e.blockId,before:e.before,after:e.after,reason:e.reason}))},source);const doc=studioDoc(docId);if(!doc)throw new Error('The document is no longer available.');const next={...doc,review:{...doc.review,edits:[...doc.review.edits,...incoming]}};if(!await saveStudioDocument(next))throw new Error('The suggestions could not be saved. Try again.');editDocumentId=docId;}const applicationActions=(d.applicationActions||[]).slice(0,1);for(const a of applicationActions){if(!a||typeof a.id!=='string'||typeof a.title!=='string'||(a.documentId&&!requestWorkspace.documents.some(x=>x.id===a.documentId))||(a.grant&&(!/^\d{1,10}$/.test(a.grant.id)||a.grant.url!=='https://www.grants.gov/search-results-detail/'+a.grant.id)))throw new Error('Beedy returned an invalid application setup.');}const grantActions=(d.grantActions||[]).slice(0,2);for(const action of grantActions){if(!action?.grant||!/^\d{1,10}$/.test(action.grant.id)||action.grant.url!=='https://www.grants.gov/search-results-detail/'+action.grant.id)throw new Error('Beedy returned an invalid opportunity.');if(action.documentId&&!requestWorkspace.documents.some(x=>x.id===action.documentId))throw new Error('The linked document was not attached.');}let insightSaved=false;if(insightDocumentId){const target=studioDoc(insightDocumentId);if(!target||target.opportunity?.id!==insightGrantId)throw new Error('The linked opportunity changed. Run the analysis again.');insightSaved=await saveStudioDocument({...target,opportunityInsights:{text:d.answer,grantId:insightGrantId,createdAt:new Date().toISOString()}});if(!insightSaved)throw new Error('Could not save the grant analysis. Try again.');}finishRun(run);currentRun=null;state.chat.push({id:crypto.randomUUID(),role:'assistant',activity:run,text:d.answer,grantResults:d.grantResults||[],grantActions,applicationActions,insightDocumentId:insightSaved?insightDocumentId:null,proposals:d.proposals,editDocumentId,editCount:incoming.length,elapsed:Math.max(1,Math.round((Date.now()-started)/1000)),documentName:sourceName});state.chat=state.chat.slice(-40);persist();}catch(error){agentError=error.name==='TimeoutError'?'Beedy took too long. Please try again.':error.message;finishRun(run,agentError);chatDraft=question;}finally{agentBusy=false;if(route().startsWith('studio/')&&['review','insights'].includes(studioTab))render();else refreshChat();}}
function findProposal(button){return state.chat.find(m=>m.id===button.dataset.message)?.proposals?.find(p=>p.id===button.dataset.id)}
function applyAgentProposal(p){if(!p||p.applied||p.undone||(state.appliedChanges||[]).includes(p.id))return;try{validateChange(p.change,state);const current=localTarget(p.change);if(fingerprint(current)!==p.before)throw new Error('This record changed after Beedy’s suggestion. Ask for a fresh proposal.');p.undo=structuredClone(current);p.appliedId=applyChange(p.change,state,crypto.randomUUID());p.after=fingerprint(p.change.kind==='task_create'?state.tasks.find(t=>t.id===p.appliedId):localTarget(p.change));p.applied=true;state.appliedChanges=(state.appliedChanges||[]).concat(p.id).slice(-200);persist();render();toast('Change applied to your workspace');}catch(error){toast(error.message)}}
function undoAgentProposal(p){if(!p?.applied)return;const current=p.change.kind==='task_create'?state.tasks.find(t=>t.id===p.appliedId):localTarget(p.change);if(fingerprint(current)!==p.after){toast('This item has changed since then. Edit it directly to keep your newer work.');return;}if(p.change.kind==='task_create')state.tasks=state.tasks.filter(t=>t.id!==p.appliedId);else if(p.change.kind==='task_update'){const i=state.tasks.findIndex(t=>t.id===p.change.id);state.tasks[i]=p.undo;}else if(p.change.kind==='application_update')state.applications[p.change.id]=p.undo;else state.readiness[p.change.id]=p.undo;p.applied=false;p.undone=true;persist();render();toast('Change undone');}
let navigationPinned=localStorage.getItem('centring-navigation-pinned')!=='false';
