let reviewPreview=false,reviewActionBusy=false,draftOpportunity=null,reviewMode='suggestions',organisationProfile=null;
async function ensureDocumentReview(id){const d=studioDoc(id);if(!d)return null;if(d.applicationDraft)return d;const next=await prepareDocumentReview(d);if(next!==d&&!await saveStudioDocument(next))throw new Error('Could not prepare the document for review.');syncBeedyDocument();return studioDoc(id);}
