async function analyseLinkedGrant(id){const d=studioDoc(id);if(!d?.opportunity)throw new Error('Link an opportunity first.');pinnedDocumentId=id;excludedDocumentId=null;syncBeedyDocument();chatOpen=true;studioTab='insights';go('studio/'+id);await checkAgentConnection();await replyToBeedy('Analyse the linked Grants.gov opportunity '+d.opportunity.id+' against my attached document. Refresh the official notice and inspect my document. If the attached document is an imported grant notice, use referenceSource as the programme evidence; do not compare the notice to itself or call the funder’s programme our mission. Use the account organisation profile for mission and organisation facts. If no project evidence is attached, assess thematic fit from the profile and flag project details and eligibility still needed. Write a grant working brief of at most 400 words, using clear Markdown headings and short bullets, with: fit and eligibility to confirm; requirements with evidence from the document or missing information; actual application deadlines and closing-time notes; mission and programme starting wording using only documented facts (mark missing facts); next steps. Cite official notice links and document page or paragraph references. Distinguish requirements from your recommendations. Do not treat old example dates in my document as this grant’s deadline. This answer will be saved under Grant analysis for this document. Do not import it again.',{insightDocumentId:id,insightGrantId:d.opportunity.id,displayQuestion:'Review '+d.opportunity.name+' against '+d.name+'. Find requirements, deadlines, and gaps, then draft a starting mission paragraph.'});}
