 if(b.dataset.action==='grant-notes'){if(d?.opportunityInsights){const addition='GRANT ANALYSIS — '+d.opportunity.name+'\n\n'+d.opportunityInsights.text;const existing=d.draft?.text||'';if(existing.includes(addition)){toast('This analysis is already in your draft notes.');return;}if(existing.length+addition.length>120000)throw new Error('Draft notes are full. Download the analysis instead.');if(await saveStudioDocument({...d,previousDraft:existing,draft:{...d.draft,text:[existing,addition].filter(Boolean).join('\n\n')}})){studioTab='draft';render();toast('Added to draft notes. Original unchanged.');}}return;}
 if(grantImportBusy||agentBusy)return;const a=findGrantAction(id);if(!a||(a.status==='imported'&&b.dataset.action!=='grant-save-document'))return;grantImportBusy=true;b.disabled=true;b.textContent='Importing…';
 const response=await fetch('/api/grants/'+encodeURIComponent(a.grant.id));const g=await response.json();if(!response.ok)throw new Error(g.error||'Could not refresh this notice.');if(g.id!==a.grant.id)throw new Error('The notice does not match this import.');
 const imported=await saveGrantNotice(g,a.documentId,id);grantImportBusy=false;studioFilter='favorites';studioSearch='';studioTab='insights';pinnedDocumentId=imported.id;excludedDocumentId=null;go('studio/'+imported.id);render();toast('Saved in Documents and Saved opportunities.');await analyseLinkedGrant(imported.id);
