async function saveApplicationDraft(application,{source=null,template=null,references=[],originals={},checkedAt=null,legacyCase=null,draftActivity=null}={}){
 const text=applicationText(application),original=await newDraftDocx(text),now=new Date().toISOString();
 const doc={id:legacyCase?'case-draft-'+legacyCase:crypto.randomUUID(),legacyCase,draftActivity,name:(application.title||'Application').replace(/[\\/:*?"<>|\u0000-\u001f]/g,' ').slice(0,100)+' — application.docx',type:original.type,size:original.size,text,original,createdAt:now,updatedAt:now,extractionVersion:2,draft:{text:'',fields:{}},application:'',starred:true,applicationDraft:application,opportunity:application.grant||null,citationOriginals:originals,retrievalCheckedAt:checkedAt,retrievedReferences:references,applicationTemplate:template?{id:template.id,name:template.name}:null,referenceSource:source?{id:source.id,name:source.name,text:source.text.slice(0,60000)}:null};
 if(legacyCase){await createSampleIfMissing(doc);studioDocuments=await allDocuments();return studioDoc(doc.id);}
 await putDocument(doc);studioDocuments.unshift(doc);return doc;
}
